CustomField.formula:
IF(
NOT(ISBLANK(Override_License_Start_Date__c)),
Override_License_Start_Date__c,
IF(
OR(TEXT(Subscription__r.SBQQ__QuoteLine__r.Transaction_Type__c) = 'Renewal',
Subscription_Start_Date__c < TODAY()),
TODAY(),
Subscription_Start_Date__c
)
)

/*IF(
    NOT(ISBLANK(Override_License_Start_Date__c)),
    Override_License_Start_Date__c,
