        OR(
            TEXT(Subscription__r.SBQQ__QuoteLine__r.Transaction_Type__c) <> 'Renewal',
            AND(TEXT(Subscription__r.SBQQ__QuoteLine__r.Transaction_Type__c) = 'Renewal', 
                TEXT(Server_Deployment__r.Server_Device_Type__c) = 'On-Prem')
        ),
        Subscription_Start_Date__c,
        IF(
            OR(
                AND(TEXT(Server_Deployment__r.Server_Device_Type__c) = 'On-Prem', 
                    TEXT(Subscription__r.SBQQ__QuoteLine__r.Transaction_Type__c) <> 'Renewal'
                ),
                AND(
                    TEXT(Subscription__r.SBQQ__QuoteLine__r.Transaction_Type__c) = 'Renewal',
                    Subscription_Start_Date__c < TODAY()
                )
            ),
            TODAY(),
            Subscription_Start_Date__c
        )
    )
)*/


